// Internal encoding structures
// ABS: Absolute value (vector)
// Encoding: ABS_asisdmisc_R
// Template: ABS  D<d>, D<n>
struct AbsAsisdmiscR {
    uint32_t Rd : 5;
    uint32_t Rn : 5;
    uint32_t _unnamed_5 : 2;  // fixed: 0b10 (0x2)
    uint32_t opcode : 5;  // fixed: 0b01011 (0xB)
    uint32_t _unnamed_4 : 5;  // fixed: 0b10000 (0x10)
    uint32_t size : 2;  // fixed: 0b11 (0x3)
    uint32_t _unnamed_3 : 1;  // fixed: 0b0 (0x0)
    uint32_t _unnamed_2 : 3;  // fixed: 0b111 (0x7)
    uint32_t _unnamed_1 : 1;  // fixed: 0b1 (0x1)
    uint32_t U : 1;  // fixed: 0b0 (0x0)
    uint32_t _unnamed_0 : 2;  // fixed: 0b01 (0x1)
};


